mapper.select:
SELECT pspf.PORTFOLIO_ID, pspf.FINPROD_ID, pspf.SEC_ACCT_ID, pspf.CCY,
pspf.INV_AIM, CASE WHEN ava.INV_AIM = #{INV_AIM_AC} THEN 1 WHEN ava.INV_AIM = #{INV_AIM_FVOCI} THEN 2 WHEN ava.INV_AIM = #{INV_AIM_FVTPL} THEN 3 ELSE 0 END invAimSort,
SUM(IFNULL(pspf.AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION_FLOW pspf LEFT JOIN TRD_STASEC_FLOW tsf ON tsf.SEQNO = pspf.TRADE_ID AND tsf.PORTFOLIO_ID = pspf.PORTFOLIO_ID AND tsf.SEC_ACCT_ID = pspf.SEC_ACCT_ID WHERE pspf.HODING_TYPE = #{POSITION_TYPE_04} AND tsf.SEQNO IS NOT NULL AND tsf.SEQNO != ''
AND pspf.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND pspf.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND pspf.FINPROD_ID = #{finProdId, jdbcType=VARCHAR}
AND date_format(pspf.CDATE, '%Y-%m-%d') <= #{searchDate, jdbcType=VARCHAR}
GROUP BY pspf.PORTFOLIO_ID, pspf.FINPROD_ID, pspf.SEC_ACCT_ID, pspf.CCY
,pspf.INV_AIM

mapper.insert:
INSERT INTO TRD_PRODUCT_DEAL_ADD (TRADE_ID, PORTFOLIO_ID, CUSTOM_CASH_TYPE, GEN_TYPE, PUR_CFM_DATE, RED_CFM_DATE, REG_DATE_AMT,
REG_DATE, BONUS_CFM_DATE, ENTRUST_ID, PAY_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) values concat(IFNULL(TRADE_ID,''),'R'), PORTFOLIO_ID, CUSTOM_CASH_TYPE, GEN_TYPE, PUR_CFM_DATE, RED_CFM_DATE, REG_DATE_AMT,
REG_DATE, BONUS_CFM_DATE, ENTRUST_ID, PAY_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, #{updateUser}, CURRENT_TIMESTAMP FROM TRD_PRODUCT_DEAL_ADD where TRADE_ID = #{bizCode}
